/// One detector with its pattern compiled.
#[derive(Debug)]
pub struct CompiledDetector {
    /// The detector this is the compiled form of.
    pub detector: &'static Detector,
    /// Its pattern, compiled once.
    pub pattern: ::regex::Regex,
}

/// [`DETECTOR_CATALOG`] with every pattern compiled, built ONCE for the process.
///
/// A pattern is a constant of this module, so compiling it cannot fail on request content
/// and no request ever compiles one.
pub static DETECTORS: LazyLock<Vec<CompiledDetector>> = LazyLock::new(|| {
    DETECTOR_CATALOG
        .iter()
        .map(|detector| CompiledDetector {
            detector,
            pattern: ::regex::Regex::new(detector.pattern)
                .expect("every detector pattern of this module is a constant that compiles"),
        })
        .collect()
});

/// One file of an uploaded archive, as the detectors read it.
#[derive(Debug, Clone)]
pub struct SourceFile {
    /// The path the archive holds the file under.
    pub path: String,
    /// Its content, as text.
    pub text: String,
}

/// One detection: the finding identifier it is reported under, and the finding itself.
///
/// The finding carries everything the detector and the location decide. The instants are
/// left unset, because WHEN a finding came into existence is the instant the run that
/// found it recorded it ([`crate::state::Store::apply_run_findings`]), not the instant the
/// archive was read.
#[derive(Debug, Clone)]
pub struct Detection {
    /// The `findingId` this detection is reported under; see [`finding_identifier`].
    pub finding_id: String,
    /// The finding, with `createdAt` and `updatedAt` left to the store to stamp.
    pub finding: Finding,
}

/// What one archive's analysis found, and whether it COVERS the whole resource.
///
/// The coverage matters as much as the findings do: a scan's findings are reconciled with
/// what the scan already holds ([`crate::state::Store::apply_run_findings`]), and a finding
/// the scan holds that a run did not report is treated as remediated — which is only sound
/// where the run actually read the whole resource. An archive this module could not read as
/// a container, or one whose detections were cut at [`FINDINGS_PER_ANALYSIS`], says nothing
/// about the weaknesses it did not report, so it closes nothing.
#[derive(Debug, Clone, Default)]
pub struct ArchiveAnalysis {
    /// What the detectors found, in the order the files and lines were read.
    pub detections: Vec<Detection>,
    /// Whether this analysis covers the whole resource: every source file of the container
    /// was read in full AND the detections were not cut at a bound. `false` for an archive
    /// that is not a readable container, for one a bound kept source out of
    /// ([`ExtractedSources::complete`]) and for one carrying more weaknesses than one
    /// analysis reports — in each case what is NOT in `detections` is unknown rather than
    /// absent.
    pub complete: bool,
}

/// The language of the file at `path`, or `None` when its extension names none of
/// [`LANGUAGES`].
pub fn language_of(path: &str) -> Option<&'static Language> {
    let name = path.rsplit('/').next().unwrap_or(path);
    let extension = name.rsplit_once('.')?.1.to_ascii_lowercase();
    LANGUAGES
        .iter()
        .find(|language| language.extensions.contains(&extension.as_str()))
}

/// Analyse the archive `bytes` that arrived for `scan_name`: every finding its code
/// carries, in the order the files and lines were read, and whether that analysis covers
/// the whole resource ([`ArchiveAnalysis`]).
///
/// An archive this module cannot read as a container — one that is not a zip, or one cut
/// short — yields no findings AND no coverage, so a run on it reports nothing and closes
/// nothing: an upload that could not be read is not a resource whose weaknesses were
/// remediated. A container that WAS read and carries no detectable code is covered: there
/// the empty set is the answer. Whether a resource was uploaded at all is the run's own
/// question (`crate::state::SCAN_RESOURCE_NOT_UPLOADED_MESSAGE`).
pub fn analyse_archive(scan_name: &str, bytes: &[u8]) -> ArchiveAnalysis {
    let Some(extracted) = extract_sources(bytes) else {
        return ArchiveAnalysis::default();
    };
    let (detections, truncated) = detect(scan_name, &extracted.files);
    ArchiveAnalysis {
        detections,
        // Covered only where the WHOLE resource was read and the WHOLE of what the
        // detectors found is reported: a file a bound kept this analysis from reading, and
        // a detection list cut at a bound, both leave weaknesses this analysis cannot speak
        // for.
        complete: extracted.complete && !truncated,
    }
}

/// What [`extract_sources`] read out of one archive: its source files, and whether they
/// are ALL of the source the archive carries.
#[derive(Debug, Clone, Default)]
pub struct ExtractedSources {
    /// The files that were read, bounded as this module's header states.
    pub files: Vec<SourceFile>,
    /// Whether every source file of the archive was read in full. `false` where a bound
    /// kept a file out: a file past [`MAX_SOURCE_FILE_BYTES`], an entry the archive's own
    /// budget ([`MAX_SOURCE_BYTES`], [`MAX_SOURCE_FILES`], [`MAX_ARCHIVE_ENTRIES`]) left no
    /// room for, or an entry of a covered language whose bytes could not be read as text.
    pub complete: bool,
}

/// Every source file of the zip archive `bytes`, bounded as this module's header states,
/// or `None` when `bytes` is not a zip container this module can read at all.
///
/// Reading the container is the `zip` crate's job. What this function owns is the bounds
/// and which entries are source at all: a directory, a name that escapes the archive, a
/// file of a language this detector set does not cover, a file past
/// [`MAX_SOURCE_FILE_BYTES`] and an entry whose bytes are not text are each skipped, so a
/// malformed or hostile archive costs the bounds and produces what could be read — and
/// reports, in [`ExtractedSources::complete`], whether a bound kept anything out.
pub fn extract_sources(bytes: &[u8]) -> Option<ExtractedSources> {
    let Ok(mut archive) = ::zip::ZipArchive::new(::std::io::Cursor::new(bytes)) else {
        return None;
    };
    let visiting = archive.len().min(MAX_ARCHIVE_ENTRIES);
    let mut sources: Vec<SourceFile> = Vec::new();
    let mut taken = 0usize;
    // Set wherever a BOUND of this module keeps source out of the analysis, so what is
    // reported can be told from what was not read.
    let mut bounded_out = archive.len() > visiting;
    for index in 0..visiting {
        if sources.len() >= MAX_SOURCE_FILES || taken >= MAX_SOURCE_BYTES {
            bounded_out = true;
            break;
        }
        let Ok(mut entry) = archive.by_index(index) else {
            continue;
        };
        // zip reports an entry's name as a `Result`, because a name that is not valid
        // UTF-8 cannot be reported as a file path at all.
        let Ok(name) = entry.name() else {
            continue;
        };
        let path = name.to_string();
        if path.ends_with('/') {
            continue;
        }
        if path.starts_with('/') || path.split('/').any(|segment| segment == "..") {
            continue;
        }
        if language_of(&path).is_none() {
            continue;
        }
        // The remaining budget, and one byte more: reading MORE than the budget is what
        // says the entry is past it, and the limited reader stops there whatever the
        // entry's own header claimed its size to be.
        let allowed = MAX_SOURCE_BYTES
            .saturating_sub(taken)
            .min(MAX_SOURCE_FILE_BYTES);
        let mut body: Vec<u8> = Vec::new();
        let limit = u64::try_from(allowed).unwrap_or(u64::MAX).saturating_add(1);
        let read = entry.by_ref().take(limit).read_to_end(&mut body);
        // Every byte INFLATED is charged against the archive's budget, whether or not the
        // entry it came from is kept: what bounds the decompression work of one archive is
        // the budget, so an archive of entries that are each just past the per-file bound
        // (or that fail to inflate at all) buys no more of it than one that is read.
        taken = taken.saturating_add(body.len());
        if read.is_err() || body.len() > allowed {
            bounded_out = true;
            continue;
        }
        let Ok(text) = String::from_utf8(body) else {
            bounded_out = true;
            continue;
        };
        sources.push(SourceFile { path, text });
    }
    Some(ExtractedSources {
        files: sources,
        complete: !bounded_out,
    })
}

/// Run the detectors over `sources`: one detection per instance found, and whether
/// anything was CUT at a bound — the list at [`FINDINGS_PER_ANALYSIS`] or a file at
/// [`MAX_LINES_PER_FILE`] (`true` means there may be more weaknesses than the list
/// reports).
///
/// One line can carry one instance of each detector, and the same instance found again in
/// another place is another detection: a detection is identified by the detector, the file
/// and the offending text, so the same weakness in two places is two findings and the same
/// weakness in the same place is one finding across re-runs ([`finding_identifier`]).
pub fn detect(scan_name: &str, sources: &[SourceFile]) -> (Vec<Detection>, bool) {
    let mut detections: Vec<Detection> = Vec::new();
    let mut truncated = false;
    // How many instances of one detector on ONE offending text have already been found in
    // one file, so two identical offending lines of a file are told apart — and so that
    // which instance a finding is cannot change because another line of the same file
    // moved, since a finding's identity is what it is and not the order it was found in.
    let mut occurrences: BTreeMap<(&str, &str, &str), usize> = BTreeMap::new();
    for source in sources {
        let Some(language) = language_of(&source.path) else {
            continue;
        };
        for (offset, line) in source.text.lines().enumerate() {
            if offset >= MAX_LINES_PER_FILE {
                truncated = true;
                break;
            }
            for compiled in DETECTORS.iter() {
                if !compiled.detector.languages.contains(&language.slug) {
                    continue;
                }
                if !compiled.pattern.is_match(line) {
                    continue;
                }
                if detections.len() >= FINDINGS_PER_ANALYSIS {
                    return (detections, true);
                }
                let occurrence = occurrences
                    .entry((source.path.as_str(), compiled.detector.slug, line.trim()))
                    .or_default();
                let line_number = i32::try_from(offset.saturating_add(1)).unwrap_or(i32::MAX);
                detections.push(detection(
                    scan_name,
                    language,
                    compiled.detector,
                    &MatchSite {
                        path: &source.path,
                        line_number,
                        line,
                        occurrence: *occurrence,
                    },
                ));
                *occurrence = occurrence.saturating_add(1);
            }
        }
    }
    (detections, truncated)
}

/// The `findingId` one detection is reported under.
///
/// A finding identifies a WEAKNESS IN A PLACE, not one run's observation of it: a re-run of
/// a scan over unchanged code has to report the finding it reported before, under the same
/// identifier, so that `BatchGetFindings` resolves an identifier an earlier `GetFindings`
/// handed out and so that a finding's `createdAt` keeps naming when it was first reported.
/// The identifier is therefore DERIVED from what the finding is — the scan it belongs to,
/// the detector that found it, the file, the offending text and which instance of that text
/// in that file it is — and from nothing of the run, the clock or the request. The LINE
/// NUMBER is deliberately not part of it, because code that moves is the same finding
/// ("Findings are updated ... when the finding code location changes", `Finding$updatedAt`).
///
/// The form is the `Uuid` the model gives every identifier this service issues
/// (`crate::state::derived_identifier`), so an identifier handed out here resolves back
/// through the operations that take one.
pub fn finding_identifier(
    scan_name: &str,
    detector_id: &str,
    path: &str,
    offending_text: &str,
    occurrence: usize,
) -> String {
    let occurrence = occurrence.to_string();
    crate::state::derived_identifier(&[
        scan_name,
        detector_id,
        path,
        offending_text.trim(),
        &occurrence,
    ])
}

/// Where a detector matched: the file, the 1-based line, the line itself and which
/// instance of that detector in that file this is.
struct MatchSite<'a> {
    path: &'a str,
    line_number: i32,
    line: &'a str,
    occurrence: usize,
}

/// One detection as the modelled [`Finding`].
fn detection(
    scan_name: &str,
    language: &Language,
    detector: &Detector,
    site: &MatchSite<'_>,
) -> Detection {
    let detector_id = detector_id(language, detector);
    let finding_id = finding_identifier(
        scan_name,
        &detector_id,
        site.path,
        site.line,
        site.occurrence,
    );
    let cwe = cwe_label(detector.cwe);
    let line_number = site.line_number;
    let path = site.path;
    let finding = Finding {
        created_at: None,
        updated_at: None,
        description: Some(detector.description.to_string()),
        generator_id: Some(GENERATOR_ID.to_string()),
        id: Some(finding_id.clone()),
        r#type: Some(format!("{FINDING_TYPE_NAMESPACE}/{cwe}")),
        status: Some(crate::state::STATUS_OPEN.to_string()),
        resource: Some(Resource {
            // "The scanName of the scan that was run on the resource" (`Resource$id`), and
            // the section of it this finding is in (`Resource$subResourceId`).
            id: Some(scan_name.to_string()),
            sub_resource_id: Some(path.to_string()),
        }),
        vulnerability: Some(Vulnerability {
            reference_urls: Some(vec![format!(
                "{CWE_REFERENCE_URL_PREFIX}{number}.html",
                number = detector.cwe
            )]),
            // Nothing here relates one weakness class to another, so a finding reports no
            // related vulnerability rather than reporting itself as one.
            related_vulnerabilities: None,
            id: Some(cwe.clone()),
            file_path: Some(FilePath {
                name: Some(file_name(path).to_string()),
                path: Some(path.to_string()),
                start_line: Some(line_number),
                end_line: Some(line_number),
                code_snippet: Some(vec![CodeLine {
                    number: Some(line_number),
                    content: Some(snippet_line(site.line)),
                }]),
            }),
            // `Vulnerability$itemCount` is deprecated in the model ("This shape is not
            // used"), so nothing reports it.
            item_count: None,
        }),
        severity: Some(detector.severity.to_string()),
        remediation: Some(Remediation {
            recommendation: Some(Recommendation {
                text: Some(detector.recommendation.to_string()),
                url: Some(detector_url(language, detector)),
            }),
            // A suggested fix is a code patch for the caller's own code, which this
            // analysis does not produce, so none is reported rather than an empty one.
            suggested_fixes: None,
        }),
        title: Some(format!("{cwe} - {name}", name = detector.name)),
        detector_tags: Some(vec![
            SECURITY_TAG.to_string(),
            detector.category.to_string(),
            language.slug.to_string(),
        ]),
        detector_id: Some(detector_id.clone()),
        detector_name: Some(detector.name.to_string()),
        // "The identifier for the rule that generated the finding" — the detector's rule,
        // which the versioned detector identifier above is one version of.
        rule_id: Some(format!(
            "{slug}/{detector}",
            slug = language.slug,
            detector = detector.slug
        )),
    };
    Detection {
        finding_id,
        finding,
    }
}

/// `Finding$detectorId` — the detector that found it, in the language it found it in, at
/// the version that found it.
pub fn detector_id(language: &Language, detector: &Detector) -> String {
    format!(
        "{language}/{detector}@{DETECTOR_VERSION}",
        language = language.slug,
        detector = detector.slug
    )
}

/// Where `detector` is published for `language`, which is what a finding's recommendation
/// points the caller at.
pub fn detector_url(language: &Language, detector: &Detector) -> String {
    format!(
        "{DETECTOR_LIBRARY_URL_PREFIX}{language}/{detector}/",
        language = language.slug,
        detector = detector.slug
    )
}

/// A CWE class as it is spelled in a finding's `type`, `title` and `vulnerability.id`.
pub fn cwe_label(number: u32) -> String {
    format!("CWE-{number}")
}

/// The file name of `path` — its last segment ("The name of the file", `FilePath$name`).
fn file_name(path: &str) -> &str {
    path.rsplit('/').next().unwrap_or(path)
}

/// The offending line as a `CodeLine$content`: the line with its indentation and trailing
/// whitespace dropped, cut to [`SNIPPET_LINE_MAX_CHARS`] CHARACTERS (never to a byte
/// boundary inside one), so a snippet of a very long line stays a bounded, valid string.
fn snippet_line(line: &str) -> String {
    line.trim().chars().take(SNIPPET_LINE_MAX_CHARS).collect()
}

/// Where in the code a stored finding says it is: the file and the line span its
/// `vulnerability.filePath` names.
///
/// The ONE reading of a finding's location, so the store decides "the same finding has
/// moved" exactly where the analysis decides where it is.
pub fn location_of(finding: &Finding) -> (Option<String>, Option<i32>, Option<i32>) {
    let file_path = finding
        .vulnerability
        .as_ref()
        .and_then(|vulnerability| vulnerability.file_path.as_ref());
    match file_path {
        Some(path) => (path.path.clone(), path.start_line, path.end_line),
        None => (None, None, None),
    }
}
